"""Decoder di transazioni Bitcoin raw (legacy e SegWit) + classificatore di script
alla maniera di ScriptParser.typeFromOut/addrFromOut delle slide LAB04, esteso a P2TR."""
import hashlib, json, sys

def sha256(b): return hashlib.sha256(b).digest()
def dsha(b): return sha256(sha256(b))
def hash160(b): return hashlib.new('ripemd160', sha256(b)).digest()

# ---------- lettura ----------
class R:
    def __init__(s, b): s.b = b; s.i = 0
    def take(s, n):
        r = s.b[s.i:s.i+n]; s.i += n; return r
    def u32(s): return int.from_bytes(s.take(4), 'little')
    def u64(s): return int.from_bytes(s.take(8), 'little')
    def varint(s):
        f = s.take(1)[0]
        if f < 0xfd: return f
        return int.from_bytes(s.take({0xfd: 2, 0xfe: 4, 0xff: 8}[f]), 'little')

def varint(n):
    if n < 0xfd: return bytes([n])
    if n <= 0xffff: return b'\xfd' + n.to_bytes(2, 'little')
    if n <= 0xffffffff: return b'\xfe' + n.to_bytes(4, 'little')
    return b'\xff' + n.to_bytes(8, 'little')

def parse_tx(hexs):
    raw = bytes.fromhex(hexs); r = R(raw)
    tx = {'version': r.u32()}
    segwit = raw[4] == 0 and raw[5] == 1
    if segwit: r.take(2)
    tx['segwit'] = segwit
    tx['vin'] = []
    for _ in range(r.varint()):
        prev = r.take(32)[::-1].hex(); idx = r.u32()
        ss = r.take(r.varint()); seq = r.u32()
        tx['vin'].append({'prev_txid': prev, 'vout': idx, 'scriptSig': ss, 'sequence': seq})
    tx['vout'] = []
    for _ in range(r.varint()):
        v = r.u64(); spk = r.take(r.varint())
        tx['vout'].append({'value': v, 'scriptPubKey': spk})
    if segwit:
        for vin in tx['vin']:
            vin['witness'] = [r.take(r.varint()) for _ in range(r.varint())]
    tx['locktime'] = r.u32()
    assert r.i == len(raw), 'byte residui'
    # serializzazione senza witness -> txid
    base = tx['version'].to_bytes(4, 'little') + varint(len(tx['vin']))
    for v in tx['vin']:
        base += bytes.fromhex(v['prev_txid'])[::-1] + v['vout'].to_bytes(4, 'little') + varint(len(v['scriptSig'])) + v['scriptSig'] + v['sequence'].to_bytes(4, 'little')
    base += varint(len(tx['vout']))
    for o in tx['vout']:
        base += o['value'].to_bytes(8, 'little') + varint(len(o['scriptPubKey'])) + o['scriptPubKey']
    base += tx['locktime'].to_bytes(4, 'little')
    tx['txid'] = dsha(base)[::-1].hex()
    tx['wtxid'] = dsha(raw)[::-1].hex()
    tx['size'] = len(raw); tx['base_size'] = len(base)
    tx['weight'] = 3 * len(base) + len(raw)
    tx['vsize'] = -(-tx['weight'] // 4)
    return tx

# ---------- disassembler ----------
OPN = {0x00: 'OP_0', 0x4c: 'OP_PUSHDATA1', 0x4d: 'OP_PUSHDATA2', 0x4e: 'OP_PUSHDATA4', 0x4f: 'OP_1NEGATE',
       0x51: 'OP_1', 0x6a: 'OP_RETURN', 0x76: 'OP_DUP', 0x87: 'OP_EQUAL', 0x88: 'OP_EQUALVERIFY',
       0xa9: 'OP_HASH160', 0xac: 'OP_CHECKSIG', 0xad: 'OP_CHECKSIGVERIFY', 0xae: 'OP_CHECKMULTISIG', 0x61: 'OP_NOP'}
for k in range(2, 17): OPN[0x50 + k] = 'OP_%d' % k

def disasm(s, maxlen=40):
    out = []; i = 0
    while i < len(s):
        op = s[i]; i += 1
        if 1 <= op <= 0x4b:
            d = s[i:i+op]; i += op
        elif op in (0x4c, 0x4d, 0x4e):
            n = {0x4c: 1, 0x4d: 2, 0x4e: 4}[op]
            ln = int.from_bytes(s[i:i+n], 'little'); i += n
            d = s[i:i+ln]; i += ln
            out.append(OPN[op]);
        else:
            out.append(OPN.get(op, 'OP_0x%02x' % op)); continue
        h = d.hex()
        out.append(h if len(h) <= maxlen else h[:maxlen//2] + '...' + h[-8:] + '(%dB)' % len(d))
    return ' '.join(out)

# ---------- indirizzi ----------
B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
def b58check(ver, payload):
    b = bytes([ver]) + payload; b += dsha(b)[:4]
    n = int.from_bytes(b, 'big'); s = ''
    while n: n, r = divmod(n, 58); s = B58[r] + s
    return '1' * (len(b) - len(b.lstrip(b'\0'))) + s

CH = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l'
def _polymod(v):
    g = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]; c = 1
    for x in v:
        b = c >> 25; c = (c & 0x1ffffff) << 5 ^ x
        for i in range(5): c ^= g[i] if (b >> i) & 1 else 0
    return c
def _conv(data):
    acc = bits = 0; out = []
    for x in data:
        acc = (acc << 8) | x; bits += 8
        while bits >= 5: bits -= 5; out.append((acc >> bits) & 31)
    if bits: out.append((acc << (5 - bits)) & 31)
    return out
def segwit_addr(ver, prog, hrp='bc'):
    const = 1 if ver == 0 else 0x2bc830a3          # bech32 (BIP173) vs bech32m (BIP350)
    data = [ver] + _conv(prog)
    hx = [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]
    pm = _polymod(hx + data + [0] * 6) ^ const
    return hrp + '1' + ''.join(CH[d] for d in data + [(pm >> 5 * (5 - i)) & 31 for i in range(6)])

# ---------- classificatore (porting di typeFromOut, + P2PK compresso, P2MS, P2TR) ----------
def classify(s):
    if len(s) == 0: return 'EMPTY (anyone can spend)', None
    if s[0] == 0x6a: return 'RETURN (provably unspendable)', None
    if len(s) == 25 and s[:3] == b'\x76\xa9\x14' and s[-2:] == b'\x88\xac':
        return 'P2PKH', b58check(0x00, s[3:23])
    if len(s) == 67 and s[0] == 0x41 and s[-1] == 0xac:
        return 'P2PK (non compressa)', b58check(0x00, hash160(s[1:66]))
    if len(s) == 35 and s[0] == 0x21 and s[-1] == 0xac:
        return 'P2PK (compressa)', b58check(0x00, hash160(s[1:34]))
    if len(s) == 23 and s[:2] == b'\xa9\x14' and s[-1] == 0x87:
        return 'P2SH', b58check(0x05, s[2:22])
    if len(s) == 22 and s[:2] == b'\x00\x14': return 'P2WPKH', segwit_addr(0, s[2:])
    if len(s) == 34 and s[:2] == b'\x00\x20': return 'P2WSH', segwit_addr(0, s[2:])
    if len(s) == 34 and s[:2] == b'\x51\x20': return 'P2TR', segwit_addr(1, s[2:])
    if s[-1] == 0xae: return 'P2MS (bare multisig)', None
    return 'UNKNOWN', None

def scriptsig_kind(ss, wit):
    if wit and not ss: return 'SegWit nativo: scriptSig vuoto, firma nel witness'
    if wit and ss: return 'P2SH-wrapped SegWit: scriptSig = push del redeemScript'
    return 'legacy'

if __name__ == '__main__':
    txs = json.load(open('txs.json'))
    names = ['P2PKH classica (slide p.3)', 'prima tx SegWit (P2SH-P2WPKH)', 'OP_RETURN', 'P2SH 1-of-? (bitcointalk)',
             'collisione SHA-1 (bounty)', 'anyone-can-spend: crea output', 'anyone-can-spend: spende', 'taproot']
    for (lab, h, hx), nm in zip(txs, names):
        tx = parse_tx(hx)
        print('=' * 70); print(nm, '| label:', lab)
        print('txid calcolato:', tx['txid'], '| atteso:', h, '| match:', h == tx['txid'] if h else '-')
        print('version', tx['version'], 'segwit', tx['segwit'], 'locktime', tx['locktime'],
              'size', tx['size'], 'vsize', tx['vsize'], 'weight', tx['weight'])
        for i, v in enumerate(tx['vin']):
            print(' IN %d prev %s:%d seq %08x' % (i, v['prev_txid'], v['vout'], v['sequence']))
            print('    scriptSig(%dB): %s' % (len(v['scriptSig']), disasm(v['scriptSig'])))
            if v.get('witness'): print('    witness:', [w.hex()[:20] + '..(%dB)' % len(w) for w in v['witness']])
        tot = 0
        for i, o in enumerate(tx['vout']):
            t, a = classify(o['scriptPubKey']); tot += o['value']
            print(' OUT %d %d sat (%.8f BTC) %s %s' % (i, o['value'], o['value'] / 1e8, t, a))
            print('    spk(%dB): %s' % (len(o['scriptPubKey']), disasm(o['scriptPubKey'], 80)))
        print(' totale output:', tot)

