# Esercizio 3: dall'output script all'indirizzo (Base58Check per P2PKH/P2SH)
import hashlib

B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'

def dsha256(b):
    return hashlib.sha256(hashlib.sha256(b).digest()).digest()

def hash160(b):
    return hashlib.new('ripemd160', hashlib.sha256(b).digest()).digest()

def b58check(version, payload):
    data = bytes([version]) + payload
    data += dsha256(data)[:4]                       # checksum: primi 4 byte di SHA256(SHA256(.))
    n = int.from_bytes(data, 'big')
    s = ''
    while n:
        n, r = divmod(n, 58)
        s = B58[r] + s
    zeros = len(data) - len(data.lstrip(b'\x00'))   # ogni byte 0x00 iniziale diventa un '1'
    return '1' * zeros + s

def addr_from_spk(spk):
    if len(spk) == 25 and spk[:3] == b'\x76\xa9\x14' and spk[-2:] == b'\x88\xac':
        return b58check(0x00, spk[3:23])            # P2PKH
    if len(spk) == 23 and spk[:2] == b'\xa9\x14' and spk[-1] == 0x87:
        return b58check(0x05, spk[2:22])            # P2SH
    if len(spk) == 67 and spk[0] == 0x41 and spk[-1] == 0xac:
        return b58check(0x00, hash160(spk[1:66]))   # P2PK: convenzione, indirizzo P2PKH della chiave
    return None

