# Esercizio 5: estendere il classificatore a P2TR con indirizzi bech32 / bech32m
CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l'
BECH32, BECH32M = 1, 0x2bc830a3

def polymod(values):
    gen = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3]
    chk = 1
    for v in values:
        b = chk >> 25
        chk = (chk & 0x1ffffff) << 5 ^ v
        for i in range(5):
            chk ^= gen[i] if (b >> i) & 1 else 0
    return chk

def hrp_expand(hrp):
    return [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]

def to5bit(data):
    acc = bits = 0; out = []
    for x in data:
        acc = (acc << 8) | x; bits += 8
        while bits >= 5:
            bits -= 5; out.append((acc >> bits) & 31)
    if bits: out.append((acc << (5 - bits)) & 31)
    return out

def segwit_address(version, program, hrp='bc'):
    const = BECH32 if version == 0 else BECH32M        # BIP173 per v0, BIP350 per v1+
    data = [version] + to5bit(program)
    pm = polymod(hrp_expand(hrp) + data + [0] * 6) ^ const
    checksum = [(pm >> 5 * (5 - i)) & 31 for i in range(6)]
    return hrp + '1' + ''.join(CHARSET[d] for d in data + checksum)

def classify(spk):
    if len(spk) == 22 and spk[0] == 0x00 and spk[1] == 20: return 'P2WPKH', segwit_address(0, spk[2:])
    if len(spk) == 34 and spk[0] == 0x00 and spk[1] == 32: return 'P2WSH', segwit_address(0, spk[2:])
    if len(spk) == 34 and spk[0] == 0x51 and spk[1] == 32: return 'P2TR', segwit_address(1, spk[2:])
    return 'UNKNOWN', None

for h in ["51200f0c8db753acbd17343a39c2f3f4e35e4be6da749f9e35137ab220e7b238a667",
          "001453d9c40342ee880e766522c3e2b854d37f2b3cbf",
          "00148d7a0a3461e3891723e5fdf8129caa0075060cff"]:
